// ===== Panel B: split conformal coverage versus calibration size =====
(function () {
  function el(id) { return document.getElementById(id); }
  function mulberry32(a) { return function () { a |= 0; a = a + 0x6D2B79F5 | 0; var t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
  function gauss(r) { var u = 0; while (u === 0) u = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r()); }
  function draw(dist, r) {
    if (dist === 'gauss') return Math.abs(gauss(r));
    if (dist === 't3') { var z = gauss(r), c = 0; for (var i = 0; i < 3; i++) { var g = gauss(r); c += g * g; } return Math.abs(z / Math.sqrt(c / 3)); }
    return r() < 0.8 ? Math.abs(0.5 * gauss(r)) : Math.abs(3 * gauss(r));
  }
  var XMAX = { gauss: 3.5, t3: 6, mix: 9 }, NGRID = [5, 7, 10, 14, 20, 30, 45, 70, 100, 150, 220, 330, 500], REPS = 30, NTEST = 2000;
  var seed = 11, curve = null, curveKey = '', pending = false, timer = null;
